export default {
  name: 'PhotoAtlas',
  components: {
    AtlasEntryOverlay
  },
  data() {
    return {
      // 入场动效模式: 'scroll' (拟物双轴) | 'cinematic' (镜头下沉) | 'ink' (水墨晕染)
      entryEffect: localStorage.getItem('atlas_entry_effect') || 'scroll',
